(function () {
    cc.DragonTigerSessionHistoryView = cc.Class({
        extends: cc.Component,
        properties: {
            nodetemp: cc.Node,
            content:cc.Node,
            thongKeRong: cc.Label,
            thongKeHoa: cc.Label,
            thongKeHo: cc.Label
        },

        onLoad: function () {
            cc.DragonTigerController.getInstance().setDragonTigerSessionHistoryView(this);
        },
        updateGameHistoryUI: function(lstSession) {
            if (lstSession) {
                this.resetList();
                //lstSession = lstSession.reverse();
                //this.gameHistory = lstSession;
                this.updateThongKe(lstSession);
                lstSession.map((session, index) => {
                    var item = cc.instantiate(this.nodetemp);
                    this.content.addChild(item);
                    item.setPosition(0,-23);
                    item.getComponent(cc.DragonTigerSessionItem).updateItem(session.Result);
                })
            }
        },
        updateGameSoiCauUI: function(list) {
            if (list) {
                this.resetList();
                //lstSession = lstSession.reverse();
                //this.gameHistory = lstSession;
                this.updateThongKe(list);
                list.map((i, index) => {
                    var item = cc.instantiate(this.nodetemp);
                    this.content.addChild(item);
                    item.setPosition(0,-23);
                    item.getComponent(cc.DragonTigerSessionItem).updateItem(i);
                })
            }
        },
        updateThongKe:function(list){
            if (list) {
                let tkRong = list.filter(x => x.Result == 1).length;
                let tkHoa = list.filter(x => x.Result == 2).length;
                let tkHo = list.length - tkRong - tkHoa;
                this.thongKeRong.string = tkRong + '';
                this.thongKeHoa.string = tkHoa + '';
                this.thongKeHo.string = tkHo + '';
            }
        },
        resetList: function () {
            var children = this.content.children;
            for (var i = children.length - 1; i >= 0; i--) {
                this.content.removeChild(children[i]);
            }
        },
        //Chi tiet 1 phien
        sessionDetailClicked: function sessionDetailClicked(event, index) {
            if (this.gameHistory && this.gameHistory.length > index) {
                cc.DragonTigerController.getInstance().setDetailIndex(index);
                cc.DragonTigerPopupController.getInstance().createSessionDetailView();
            }
        }

    });
}).call(this);
